svg.script:
var regions={NW:['GBCHW','GBCHE','GBCMA','GBHAL','GBKWL','GBLIV','GBMAN','GBOLD','GBRCH','GBSKP','GBBOL','GBBUR','GBWGN','GBWRT','GBSLF','GBTAM','GBTRF','GBLAN','GBSFT','GBBBD','GBWRL','GBSHN','GBBPL'],SW:['GBBAS','GBDEV','GBDOR','GBPLY','GBPOL','GBSOM','GBBST'],GL:['GBCMD','GBGRE','GBHCK','GBISL','GBLBH','GBLEW','GBSWK','GBTWH','GBWND','GBWSM','GBBDG','GBBEN','GBBEX','GBBNE','GBBRY','GBCRY','GBEAL','GBENF','GBHAV','GBHIL','GBHNS','GBHRW','GBHRY','GBKTT','GBMRT','GBNWM','GBRDB','GBRIC','GBSTN','GBWFT','GBKEC','GBHMF','GBLND']};
function getRegion(id){for(var r in regions){if(regions[r].indexOf(id)>=0)return r;}return null;}
document.addEventListener('DOMContentLoaded',function(){
  document.querySelectorAll('path[fill="#B8860B"]').forEach(function(p){
    p.addEventListener('mouseenter',function(){
      var r=getRegion(p.id);if(!r)return;
      regions[r].forEach(function(id){var el=document.getElementById(id);if(el){el.style.fill='#FFD700';el.style.stroke='#FFD700';}});
    });
    p.addEventListener('mouseleave',function(){
      var r=getRegion(p.id);if(!r)return;
      regions[r].forEach(function(id){var el=document.getElementById(id);if(el){el.style.fill='#B8860B';el.style.stroke='#B8860B';}});
    });
  });
});
